          <div style={{ ...line(20), marginTop: 22, fontSize: 30, fontWeight: 400, color: "#7E8C84", maxWidth: 900 }}>
            figma.com
          </div>
        </div>
      </div>
      <div style={{ position: "absolute", right: 120, top: 120, opacity: ease(frame, 4, 18, 0, 0.5), transform: "translateY(" + badgeY + "px)", fontSize: 22, letterSpacing: 4, color: "#7E8C84" }}>
        →
